using FMODUnity;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AtrociousDecimatorCustomEnemySFXData", menuName = "Data/SFX/AtrociousDecimatorCustomEnemySFXData")]
public class AtrociousDecimatorCustomEnemySFXData : CustomEnemySFXData
{
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private HatchingChrysalisEffect hatchingChrysalisEffect;

	[SerializeField]
	private EventReference overCorrupt;

	[SerializeField]
	private EventReference cocoonOverCorrupt;

	public override void PlayCustomOverCorruptionSFX()
	{
		if (currentCorruptedAnimals.activeCorruptedAnimals.First().GetComponent<UnitEffects>().IsEffectActive(hatchingChrysalisEffect, activateFeedback: false))
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(cocoonOverCorrupt);
		}
		else
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(overCorrupt);
		}
	}
}
